import numpy as np
from phoenix.adaa_derived import (
    RawPyADAA,
    FortranADAA,
    NumPyADAA,
    CupyADAA,
    OpenClADAA,
)

print()

for mainclass in [
    RawPyADAA,
    FortranADAA,
    NumPyADAA,
    CupyADAA,
    # OpenClADAA,
]:
    MyClass = mainclass.fix_size(3)

    print(f"testing for mainclass {mainclass}:")

    foo = MyClass.from_numpy(np.arange(3, dtype=np.float64))
    print("  foo.real:", foo.real)
    bar = MyClass.from_numpy(2 + np.arange(3, dtype=np.float64))
    print("  bar.real:", bar.real)

    baz = foo + bar
    print("  baz.real:", baz.real)

    boo = baz * 11
    print("  boo.real:", boo.real)

    print("  ((foo + bar) * 10j - bar).real:", ((foo + bar) * 10j - bar).real)
    print("  ((foo + bar) * 10j - bar).imag:", ((foo + bar) * 10j - bar).imag)
    print(
        "  ((foo + bar) * 10j - bar).to_numpy():",
        ((foo + bar) * 10j - bar).to_numpy(),
    )

    test = MyClass.ones()
    print("  ones().real, ones().imag:", test.real, test.imag)
    print()
